        1,
        undefined,
        2,
        undefined,
        3,
        undefined,
        4,
        undefined,
        5,
        undefined,
        6,
      ])
        .slice(1)
        .toArray()
    ).toEqual([
      undefined,
      2,
      undefined,
      3,
      undefined,
      4,
      undefined,
      5,
      undefined,
      6,
    ]);
    expect(
      Seq([
        1,
        undefined,
        2,
        undefined,
        3,
        undefined,
        4,
        undefined,
        5,
        undefined,
        6,
      ])
        .slice(2)
        .toArray()
    ).toEqual([2, undefined, 3, undefined, 4, undefined, 5, undefined, 6]);
    expect(
      Seq([
        1,
        undefined,
        2,
        undefined,
        3,
        undefined,
        4,
        undefined,
        5,
        undefined,
        6,
      ])
        .slice(3, -3)
        .toArray()
    ).toEqual([undefined, 3, undefined, 4, undefined]); // one trailing hole.
  });

  it('can maintain indices for an keyed indexed sequence', () => {
    expect(
      Seq([1, 2, 3, 4, 5, 6]).toKeyedSeq().slice(2).entrySeq().toArray()
    ).toEqual([
