      [3, 4],
      [4, 5],
      [5, 6],
    ]);
    expect(
      Seq([1, 2, 3, 4, 5, 6]).toKeyedSeq().slice(2, 4).entrySeq().toArray()
    ).toEqual([
      [2, 3],
      [3, 4],
    ]);
  });

  it('slices an unindexed sequence', () => {
