        .toKeyedSeq()
        .slice(2)
        .reverse()
        .entrySeq()
        .toArray()
    ).toEqual([
      [5, 6],
      [4, 5],
      [3, 4],
      [2, 3],
    ]);
    expect(
      Seq([1, 2, 3, 4, 5, 6])
        .toKeyedSeq()
        .slice(2, 4)
        .reverse()
        .entrySeq()
        .toArray()
    ).toEqual([
      [3, 4],
      [2, 3],
    ]);
  });

